    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = len(s), len(t)
        # Precompute for s: for each i, j, is s[i:j] a palindrome?
        is_pal_s = [[False] * n for _ in range(n)]
        for length in range(1, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j]:
                    if length == 1 or is_pal_s[i+1][j-1]:
                        is_pal_s[i][j] = True
                else:
                    is_pal_s[i][j] = False

        # Precompute for t similarly
        is_pal_t = [[False] * m for _ in range(m)]
        for length in range(1, m + 1):
            for i in range(m - length + 1):
                j = i + length - 1
                if t[i] == t[j]:
                    if length == 1 or is_pal_t[i+1][j-1]:
                        is_pal_t[i][j] = True
                else:
                    is_pal_t[i][j] = False

        max_len = 1 if n > 0 or m > 0 else 0

        # Case 1: palindrome entirely from s
        if n > 0:
            for i in range(n):
                for j in range(i, n):
                    if is_pal_s[i][j]:
                        max_len = max(max_len, j - i + 1)

        # Case 2: palindrome entirely from t
        if m > 0:
            for i in range(m):
                for j in range(i, m):
                    if is_pal_t[i][j]:
                        max_len = max(max_len, j - i + 1)

        # Case 3: palindrome formed by s[i:j] + t[k:l]
        # This forms a string P = S_part + T_part
        # For P to be a palindrome, we need:
        #   S_part + T_part == reverse(S_part + T_part) = reverse(T_part) + reverse(S_part)
        # This implies:
        #   S_part must match the reverse of a suffix of T_part (if any overlap)
        #   and T_part must match the reverse of a prefix of S_part (if any overlap)
        # More directly: we can iterate over all possible S_part and T_part and check concatenation palindrome.
        # Given constraints (n,m <= 30), O(n^2 * m^2) is acceptable.

        for i in range(n):
            for j in range(i, n):
                left_part = s[i:j+1]
                for k in range(m):
                    for l in range(k, m):
                        right_part = t[k:l+1]
                        candidate = left_part + right_part
                        if candidate == candidate[::-1]:
                            max_len = max(max_len, len(candidate))

