        n, m = len(s), len(t)
        # Precompute longest palindromic substring starting at each position in s
        # dp_s[i][j] = True if s[i:j+1] is a palindrome
        dp_s = [[False] * n for _ in range(n)]
        for i in range(n):
            dp_s[i][i] = True
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j]:
                    dp_s[i][j] = (length == 2) or dp_s[i+1][j-1]

        # Precompute longest palindromic substring starting at each position in t
        dp_t = [[False] * m for _ in range(m)]
        for i in range(m):
            dp_t[i][i] = True
        for length in range(2, m + 1):
            for i in range(m - length + 1):
                j = i + length - 1
                if t[i] == t[j]:
                    dp_t[i][j] = (length == 2) or dp_t[i+1][j-1]

        max_len = 0

        # Try all possible substrings from s and t
        # s_sub: s[i:j+1], t_sub: t[k:l+1]
        for i in range(n):
            for j in range(i, n):
                # Optimization: only consider palindromes in s
                if not dp_s[i][j]:
                    continue
                len_s = j - i + 1
                # The palindrome formed is s_sub + t_sub
                # We need t_sub to be a palindrome such that the whole string is a palindrome.
                # The condition is: s_sub + t_sub == reverse(s_sub + t_sub)
                # => s_sub + t_sub == reverse(t_sub) + reverse(s_sub)
                # Since s_sub is a palindrome, reverse(s_sub) == s_sub
                # So we need s_sub + t_sub == reverse(t_sub) + s_sub
                # This implies that s_sub must equal the prefix of reverse(t_sub) of length len_s
                # And the remaining part of reverse(t_sub) must equal t_sub
                # Actually, a simpler approach:
                # Let A = s_sub, B = t_sub. We need A + B to be a palindrome.
                # Since A is a palindrome, we can check all palindromic B in t and see if A+B is palindrome.
